import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type InstagramCommentBubbleProps = Record<string, any>;

const InstagramCommentBubble: React.FC<InstagramCommentBubbleProps> = ({
  backgroundColor = "#E5E5E5",
  transparentBackground = true,
  durationInSeconds = 2,
  commentText = "COORDINATOR",
  username = "malloy_studio",
  bubbleColor = "#FFFFFF",
  textColor = "#262626",
  usernameColor = "#8E8E8E",
  heartColor = "#ED4956",
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Spring animations for the bubble entry and exit
  const scaleIn = spring({
    frame,
    fps,
    config: { damping: 12, mass: 0.6, stiffness: 140 }
  });

  const scaleOut = spring({
    frame: frame - (durationInFrames - 15), // Starts 15 frames before the end
    fps,
    config: { damping: 14, mass: 0.6, stiffness: 120 }
  });

  const currentScale = Math.max(0, scaleIn - scaleOut);
  
  // Interpolations mapped to the strictly increasing scale values natively 
  // without relying on negative scale interpolation issues
  const opacity = interpolate(currentScale, [0, 0.5], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  
  const yOffset = interpolate(scaleIn, [0, 1], [60, 0], { extrapolateRight: "clamp" }) 
                + interpolate(scaleOut, [0, 1], [0, 60], { extrapolateRight: "clamp" });

  // Typewriter Effect Logic
  const typeStartFrame = 12; 
  const framesPerChar = 1.5;
  const charsToShow = Math.max(0, Math.floor((frame - typeStartFrame) / framesPerChar));
  const displayedText = commentText.slice(0, charsToShow);
  const isTyping = charsToShow < commentText.length && frame >= typeStartFrame;

  // Heart Icon Pop Logic
  const heartStartFrame = typeStartFrame + Math.ceil(commentText.length * framesPerChar) + 6;
  const heartScale = spring({
    frame: frame >= heartStartFrame ? frame - heartStartFrame : 0,
    fps,
    config: { damping: 10, mass: 0.4, stiffness: 180 }
  });

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      justifyContent: "center", 
      alignItems: "center", 
      fontFamily: "Inter" 
    }}>
      <div style={{
        transform: `scale(${currentScale}) translateY(${yOffset}px)`,
        opacity,
        backgroundColor: bubbleColor,
        padding: "32px 40px",
        borderRadius: "40px",
        boxShadow: "0 24px 48px rgba(0, 0, 0, 0.08)",
        display: "flex",
        alignItems: "center",
        gap: "28px",
        maxWidth: width * 0.85,
        width: "auto",
        transition: "none",
      }}>
        {/* Instagram-style Gradient Avatar */}
        <div style={{
          width: "80px",
          height: "80px",
          borderRadius: "50%",
          background: "linear-gradient(45deg, #f09433 0%, #e6683c 25%, #dc2743 50%, #cc2366 75%, #bc1888 100%)",
          flexShrink: 0,
          transition: "none",
        }} />

        {/* Text Content Area */}
        <div style={{ 
          display: "flex", 
          flexDirection: "column", 
          gap: "8px",
          transition: "none",
        }}>
          <div style={{ 
            fontSize: "26px", 
            fontWeight: 600, 
            color: usernameColor,
            transition: "none",
          }}>
            {username}
          </div>
          <div style={{ 
            fontSize: "36px", 
            fontWeight: 600, 
            color: textColor, 
            minHeight: "44px", 
            display: "flex", 
            alignItems: "center",
            wordBreak: "break-word",
            transition: "none",
          }}>
            {displayedText}
            {/* Blinking Cursor */}
            <span style={{
              display: isTyping ? "inline-block" : "none",
              width: "4px",
              height: "36px",
              backgroundColor: textColor,
              marginLeft: "6px",
              opacity: frame % 10 < 5 ? 1 : 0,
              transition: "none",
            }} />
          </div>
        </div>

        {/* Heart Icon */}
        <div style={{ 
          marginLeft: "24px", 
          transform: `scale(${heartScale})`, 
          opacity: heartScale,
          transition: "none",
        }}>
          <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke={heartColor} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" fill={heartColor} />
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default InstagramCommentBubble;